beforeAll(() => {
    const srcContent = fs.readFileSync(srcPath, "utf8");
    const instrumenter = createInstrumenter({
        compact: false,
        esModules: false,
        coverageVariable: "__coverage__",
    });
    // Append assignment so the class is accessible as a window property
    // after Istanbul wraps the code in a function scope.
    const augmented = srcContent + "\nwindow.FlameGraph = FlameGraph;\n";
    const instrumented = instrumenter.instrumentSync(augmented, srcPath);

    dom = new JSDOM(
        '<!DOCTYPE html><html><body><div id="flame-container"></div></body></html>',
        {
            url: "http://localhost",
            runScripts: "outside-only",
        },
    );

    dom.window.console = {
        ...dom.window.console,
        log: () => {},
        warn: () => {},
        error: () => {},
    };

    // Execute the instrumented script in JSDOM's sandbox. This is NOT
    // evaluating untrusted input — the source is our own static asset
    // and this is the standard mechanism for loading non-module browser
    // scripts in a test environment (same pattern as admin-env.js).
    dom.window.eval(instrumented); // eslint-disable-line no-eval

    win = dom.window;
    FlameGraph = win.FlameGraph;
})

afterAll(() => {
    if (dom) {
        const jsCoverage = dom.window.__coverage__;
        if (jsCoverage && typeof jsCoverage === "object") {
            const target = "__VITEST_COVERAGE__";
            if (!globalThis[target]) {
                globalThis[target] = {};
            }
            for (const [filePath, fileCov] of Object.entries(jsCoverage)) {
                globalThis[target][filePath] = fileCov;
            }
        }
        dom.window.close();
        dom = null;
    }
})

