    })

after(async () => {
        // open browser on services page
        await browser.newUser();
        await browser.url(`/domain/athenz.dev.functional-test/service`);

        // delete both services used in the test
        await $(
            `.//*[local-name()="svg" and @id="delete-service-${SERVICE_NAME1}"]`
        ).click();
        await $('button*=Delete').click();

        // close successful deletion notification
        await $('div[data-wdio="alert-close"]').click();

        await $(
            `.//*[local-name()="svg" and @id="delete-service-${SERVICE_NAME2}"]`
        ).click();
        await $('button*=Delete').click();
    })

afterEach(async () => {
        // if executed test name matches - cleanup
        if (
            currentTest ===
            TEST_ENFORCE_AND_REPORT_WITH_TWO_HOSTS_STAR_OR_EMPTY_CANNOT_BE_USED_AS_HOST
        ) {
            await browser.newUser();
            await browser.url(`/domain/athenz.dev.functional-test/service`);
            await expect(browser).toHaveUrl(expect.stringContaining('athenz'));

            let deleteSvg = await $(
                `.//*[local-name()="svg" and @id="delete-service-${SERVICE_NAME_TWO_HOSTS}"]`
            );
            if (deleteSvg.isExisting()) {
                // attempt to delete only if service exists
                await deleteSvg.click();
                await $('button*=Delete').click();
            } else {
                console.warn(
                    `SERVICE FOR DELETION NOT FOUND: ${SERVICE_NAME_TWO_HOSTS}`
                );
            }
        }
        // reset current test
        currentTest = '';
    })

beforeAll(async () => {
    arcadedbContainer = await new GenericContainer("arcadedata/arcadedb:latest")
      .withExposedPorts(2480, 7687)
      .withEnvironment({
        JAVA_OPTS:
          `-Darcadedb.server.rootPassword=${PASSWORD}` +
          " -Darcadedb.server.plugins=BoltProtocolPlugin",
      })
      .withStartupTimeout(60000)
      .withWaitStrategy(Wait.forHttp("/api/v1/ready", 2480).forStatusCodeMatching((statusCode) => statusCode === 204))
      .start();

    const host = arcadedbContainer.getHost();
    const httpPort = arcadedbContainer.getMappedPort(2480);
    const boltPort = arcadedbContainer.getMappedPort(7687);

    // Create test database via HTTP API
    await httpApi(host, httpPort, { command: `create database ${DB_NAME}` });

    driver = neo4j.driver(
      `bolt://${host}:${boltPort}`,
      neo4j.auth.basic("root", PASSWORD)
    );
    session = driver.session({ database: DB_NAME });

    // Create test data
    const nodes = [
      { id: "node-1", name: "Alice", value: neo4j.int(100) },
      { id: "node-2", name: "Bob", value: neo4j.int(200) },
      { id: "node-3", name: "Charlie", value: neo4j.int(300) },
    ];
    for (const params of nodes) {
      await session.run(
        "CREATE (:TestNode {id: $id, name: $name, value: $value})",
        params
      );
    }
  })

afterAll(async () => {
    try {
      if (session) {
        await session.run("MATCH (t:TestNode) DETACH DELETE t");
        await session.close();
      }
      if (driver) await driver.close();
      if (arcadedbContainer) {
        const host = arcadedbContainer.getHost();
        const httpPort = arcadedbContainer.getMappedPort(2480);
        await httpApi(host, httpPort, { command: `drop database ${DB_NAME}` });
        await arcadedbContainer.stop();
      }
    } catch (e) {
      console.error("Cleanup error:", e.message);
    }
  })

