                    this.readAsArrayBuffer = (input) => {
                        setTimeout(() => {
                            const size = input && typeof input.size === 'number' ? input.size : FULL_SIZE;
                            this.onload({target: {result: new ArrayBuffer(size)}});
                        }, 0);
                    };
                };
            })

