                            win.__getCurrentContent() === ORIGINAL_HEADING_MD;
                    }, "viewer to sync with reset content");
                    const win = _getMdIFrameWin();
                    await awaitsFor(() => {
                        return win && win.__isSuppressingContentChange &&
