  } else if (context.meta?.result === 'fail') {
    testMetrics.failedTests++;
  } else if (context.meta?.result === 'skip') {
    testMetrics.skippedTests++;
  }

  // Cleanup test-specific resources
  await cleanupTestCase(context);
})

